window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-61818076656ea5f9"]={"versions": [{"id": "FIG-61818076656ea5f9", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm / Blockschaltbild des AUTOSAR-Basissoftware-Stacks zur Veranschaulichung der Watchdog-Architektur im Betriebszustand deaktivierter Alive-Überwachung (No Alive-supervision). Dargestellt ist die vertikale Schichtenhierarchie von Anwendungs- bzw. Software-Entities über die RTE bis hinunter zur Hardware-Ebene (HW).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entities (SE)</strong>: Instanzen <code>SE (1)</code>, <code>SE (2)</code> bis <code>SE (n)</code> (oberhalb der RTE, gestrichelt/inaktiv dargestellt).\n</li><li><strong>RTE (Runtime Environment)</strong>: Dazwischenliegende Abstraktionsschicht mit Port-Schnittstellen (Client-Server / Sockets angedeutet, hier inaktiv/ausgegraut).\n</li><li><strong>Watchdog Manager (Wdm)</strong>: Zentrale Komponente (hervorgehoben in Gelb) mit Alive-Zählern <code>AC (SE1)</code>, <code>AC (SE2)</code> bis <code>AC (SE n)</code> innerhalb eines gestrichelten Rahmens mit der Kennzeichnung <code>... disabled alive supervision</code>. Interner Kasten: <code>global supervision status = check disabled</code>.\n</li><li><strong>Watchdog Interface (WdgIf)</strong>: Unterlagerte BSW-Abstraktionsschicht, angebunden über Pfeil mit Notiz <code>use standardized interface for watchdog-triggering</code>.\n</li><li><strong>Watchdog Driver (Wdg)</strong>: Treiberebene bestehend aus Instanz für <code>internal Watchdog-HW</code> sowie optionaler Instanz (gestrichelt umrahmt mit Notiz <code>i.e. of multiple Watchdog-HW</code>) für <code>i.e. external Watchdog-HW</code>.\n</li><li><strong>HW</strong>: Hardware-Schicht mit interner und optionaler externer Watchdog-Hardware.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Alive-Supervision für alle Supervised Entities <code>SE (1)</code> bis <code>SE (n)</code> ist deaktiviert (<code>disabled alive supervision</code>). Die entsprechenden Alive Counter <code>AC (SE1)</code> bis <code>AC (SE n)</code> werden nicht aktiv ausgewertet bzw. die Statusprüfung ist inaktiv (<code>global supervision status = check disabled</code>). Ungeachtet der deaktivierten Überwachung der einzelnen Entities erfolgt weiterhin die zyklische Triggerung des Watchdogs über das Watchdog Interface (<code>use standardized interface for watchdog-triggering</code>) an die Watchdog-Treiber (<code>Watchdog Driver</code>) zur Bedienung der internen bzw. externen Watchdog-Hardware.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert ein spezifisches Überwachungskonfigurationsszenario: Wenn die Alive-Überwachung im Watchdog Manager konfiguriert deaktiviert ist oder in einem Zustand betrieben wird, in dem keine Alive-Prüfung gefordert ist, führt der Watchdog Manager dennoch die standardisierte Triggerung der Hardware-Watchdogs über das WdgIf aus, um einen ECU-Reset durch ablaufende Hardware-Timer zu verhindern. Relevant für die Konfiguration der BSW-Parameter des Wdm bezüglich Überwachungsmodi und Watchdog-Triggerung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-56a16c15259c590e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm / Blockschaltbild des AUTOSAR-Basissoftware-Stacks zur Veranschaulichung der Watchdog-Architektur im Betriebszustand deaktivierter Alive-Überwachung (No Alive-supervision). Dargestellt ist die vertikale Schichtenhierarchie von Anwendungs- bzw. Software-Entities über die RTE bis hinunter zur Hardware-Ebene (HW).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entities (SE)</strong>: Instanzen <code>SE (1)</code>, <code>SE (2)</code> bis <code>SE (n)</code> (oberhalb der RTE, gestrichelt/inaktiv dargestellt).\n</li><li><strong>RTE (Runtime Environment)</strong>: Dazwischenliegende Abstraktionsschicht mit Port-Schnittstellen (Client-Server / Sockets angedeutet, hier inaktiv/ausgegraut).\n</li><li><strong>Watchdog Manager (Wdm)</strong>: Zentrale Komponente (hervorgehoben in Gelb) mit Alive-Zählern <code>AC (SE1)</code>, <code>AC (SE2)</code> bis <code>AC (SE n)</code> innerhalb eines gestrichelten Rahmens mit der Kennzeichnung <code>... disabled alive supervision</code>. Interner Kasten: <code>global supervision status = check disabled</code>.\n</li><li><strong>Watchdog Interface (WdgIf)</strong>: Unterlagerte BSW-Abstraktionsschicht, angebunden über Pfeil mit Notiz <code>use standardized interface for watchdog-triggering</code>.\n</li><li><strong>Watchdog Driver (Wdg)</strong>: Treiberebene bestehend aus Instanz für <code>internal Watchdog-HW</code> sowie optionaler Instanz (gestrichelt umrahmt mit Notiz <code>i.e. of multiple Watchdog-HW</code>) für <code>i.e. external Watchdog-HW</code>.\n</li><li><strong>HW</strong>: Hardware-Schicht mit interner und optionaler externer Watchdog-Hardware.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Alive-Supervision für alle Supervised Entities <code>SE (1)</code> bis <code>SE (n)</code> ist deaktiviert (<code>disabled alive supervision</code>). Die entsprechenden Alive Counter <code>AC (SE1)</code> bis <code>AC (SE n)</code> werden nicht aktiv ausgewertet bzw. die Statusprüfung ist inaktiv (<code>global supervision status = check disabled</code>). Ungeachtet der deaktivierten Überwachung der einzelnen Entities erfolgt weiterhin die zyklische Triggerung des Watchdogs über das Watchdog Interface (<code>use standardized interface for watchdog-triggering</code>) an die Watchdog-Treiber (<code>Watchdog Driver</code>) zur Bedienung der internen bzw. externen Watchdog-Hardware.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert ein spezifisches Überwachungskonfigurationsszenario: Wenn die Alive-Überwachung im Watchdog Manager konfiguriert deaktiviert ist oder in einem Zustand betrieben wird, in dem keine Alive-Prüfung gefordert ist, führt der Watchdog Manager dennoch die standardisierte Triggerung der Hardware-Watchdogs über das WdgIf aus, um einen ECU-Reset durch ablaufende Hardware-Timer zu verhindern. Relevant für die Konfiguration der BSW-Parameter des Wdm bezüglich Überwachungsmodi und Watchdog-Triggerung.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-96b78aa0a15307d2", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm / Blockschaltbild des AUTOSAR-Basissoftware-Stacks zur Veranschaulichung der Watchdog-Architektur im Betriebszustand deaktivierter Alive-Überwachung (No Alive-supervision). Dargestellt ist die vertikale Schichtenhierarchie von Anwendungs- bzw. Software-Entities über die RTE bis hinunter zur Hardware-Ebene (HW).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entities (SE)</strong>: Instanzen <code>SE (1)</code>, <code>SE (2)</code> bis <code>SE (n)</code> (oberhalb der RTE, gestrichelt/inaktiv dargestellt).\n</li><li><strong>RTE (Runtime Environment)</strong>: Dazwischenliegende Abstraktionsschicht mit Port-Schnittstellen (Client-Server / Sockets angedeutet, hier inaktiv/ausgegraut).\n</li><li><strong>Watchdog Manager (Wdm)</strong>: Zentrale Komponente (hervorgehoben in Gelb) mit Alive-Zählern <code>AC (SE1)</code>, <code>AC (SE2)</code> bis <code>AC (SE n)</code> innerhalb eines gestrichelten Rahmens mit der Kennzeichnung <code>... disabled alive supervision</code>. Interner Kasten: <code>global supervision status = check disabled</code>.\n</li><li><strong>Watchdog Interface (WdgIf)</strong>: Unterlagerte BSW-Abstraktionsschicht, angebunden über Pfeil mit Notiz <code>use standardized interface for watchdog-triggering</code>.\n</li><li><strong>Watchdog Driver (Wdg)</strong>: Treiberebene bestehend aus Instanz für <code>internal Watchdog-HW</code> sowie optionaler Instanz (gestrichelt umrahmt mit Notiz <code>i.e. of multiple Watchdog-HW</code>) für <code>i.e. external Watchdog-HW</code>.\n</li><li><strong>HW</strong>: Hardware-Schicht mit interner und optionaler externer Watchdog-Hardware.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Alive-Supervision für alle Supervised Entities <code>SE (1)</code> bis <code>SE (n)</code> ist deaktiviert (<code>disabled alive supervision</code>). Die entsprechenden Alive Counter <code>AC (SE1)</code> bis <code>AC (SE n)</code> werden nicht aktiv ausgewertet bzw. die Statusprüfung ist inaktiv (<code>global supervision status = check disabled</code>). Ungeachtet der deaktivierten Überwachung der einzelnen Entities erfolgt weiterhin die zyklische Triggerung des Watchdogs über das Watchdog Interface (<code>use standardized interface for watchdog-triggering</code>) an die Watchdog-Treiber (<code>Watchdog Driver</code>) zur Bedienung der internen bzw. externen Watchdog-Hardware.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert ein spezifisches Überwachungskonfigurationsszenario: Wenn die Alive-Überwachung im Watchdog Manager konfiguriert deaktiviert ist oder in einem Zustand betrieben wird, in dem keine Alive-Prüfung gefordert ist, führt der Watchdog Manager dennoch die standardisierte Triggerung der Hardware-Watchdogs über das WdgIf aus, um einen ECU-Reset durch ablaufende Hardware-Timer zu verhindern. Relevant für die Konfiguration der BSW-Parameter des Wdm bezüglich Überwachungsmodi und Watchdog-Triggerung.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-61818076656ea5f9", "to": "FIG-56a16c15259c590e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-56a16c15259c590e", "to": "FIG-96b78aa0a15307d2", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
